"""Deterministic offline decision report; calculations remain in the Python model."""
import json


def render_report(data):
    """Render exact model results without converting unknowns into display values."""
    if not isinstance(data, dict):
        raise ValueError('Report data must be an object')
    payload = json.dumps(data, ensure_ascii=True, sort_keys=True, separators=(',', ':'), allow_nan=False)
    payload = payload.replace('<', '\\u003c').replace('>', '\\u003e').replace('&', '\\u0026')
    return _PAGE.replace('/*__REPORT_DATA__*/', payload) + '\n'


